    expect(calls).toEqual(['before', 'after'].slice(0, 1).concat('after'))
    calls.length = 0
    expect(await (await app.request('/?a=1')).json()).toEqual({ a: '1' })
    expect(calls).toEqual(['before', 'handler', 'after'])
  })
})
